import { isFile, isSymlink, readText, readTextIfExists, removePath, writeText } from './fsx.js';
import type { ProjectPaths } from './types.js';

export const DF_GITIGNORE_CONTENT = [
  '# generated by dfl – do not edit',
  '# personal config, runtime state and install manifest',
  'local.json',
  'state.json',
  'fast-forward.json',
  'installed.json',
  '# skills rendered from *.md.hbs templates (may contain personal values)',
  '*/steps/**/*.md',
  '# temporary dirs of an interrupted flow import',
  '.dfl-*/',
  '# held while a dfl process changes the project',
  '.lock',
  '',
].join('\n');

/**
 * Marker file dfl puts into every skill dir it installs outside `.df/`: git then ignores the whole
 * directory (including the marker), so no root `.gitignore` entries are needed.
 */
export const SKILL_DIR_GITIGNORE_FILE = '.gitignore';
export const SKILL_DIR_GITIGNORE_CONTENT =
  '# generated by dfl – this skill is rendered from .df templates and may contain personal values\n*\n';

/** Marker of the legacy managed block in the root `.gitignore` (dfl no longer writes it). */
export const MANAGED_MARKER = 'dfl (managed)';

export function writeDfGitignore(paths: ProjectPaths): boolean {
  return writeText(paths.dfGitignoreFile, DF_GITIGNORE_CONTENT);
}

function blockBounds(marker: string): { start: string; end: string } {
  return { start: `# >>> ${marker} >>>`, end: `# <<< ${marker} <<<` };
}

export interface ManagedBlockOptions {
  marker?: string | undefined;
  /**
   * Lines dfl wrote into the block (e.g. the manifest's skill dirs + `/`). When a start marker has
   * no end marker, only these lines directly after it are dropped with the marker; every other
   * line is kept.
   */
  knownLines?: string[] | undefined;
  /** How warnings name the file (e.g. `.gitignore`). Default: its path. */
  displayName?: string | undefined;
}

export interface ManagedBlockResult {
  changed: boolean;
  /** Human-readable problems found (malformed block markers); nothing is ever dropped for them. */
  warnings: string[];
  /** The file was deleted because it held nothing but dfl's block. */
  deleted: boolean;
}

interface Scan {
  /** Lines outside dfl blocks (orphan markers removed, see below). */
  kept: string[];
  /** At least one well-formed block was found. */
  hadBlock: boolean;
  /** Something of dfl's was dropped: a block or an orphan start marker. */
  dropped: boolean;
  warnings: string[];
}

/**
 * Splits a gitignore-style text into the lines outside dfl's blocks. A block is a start marker
 * followed by an end marker before the next start marker. A start marker without such an end
 * marker is dropped together with the directly following `knownLines` only; an end marker without
 * a start marker is kept. User lines are never dropped.
 */
function scan(text: string, file: string, marker: string, knownLines: string[]): Scan {
  const { start, end } = blockBounds(marker);
  const known = new Set(knownLines.map((line) => line.trim()).filter((line) => line !== ''));
  const lines = text.split(/\r?\n/);
  const kept: string[] = [];
  const warnings: string[] = [];
  let hadBlock = false;
  let dropped = false;
  let i = 0;
  while (i < lines.length) {
    const line = lines[i]!;
    if (line.trim() === start) {
      let j = i + 1;
      while (j < lines.length && lines[j]!.trim() !== end && lines[j]!.trim() !== start) j++;
      dropped = true;
      if (j < lines.length && lines[j]!.trim() === end) {
        hadBlock = true;
        i = j + 1;
        continue;
      }
      // Orphan start marker: keep everything after it except dfl's own lines right below it.
      warnings.push(`${file}: the "${start}" line has no matching "${end}" line; removed only dfl's marker, kept all other lines.`);
      i++;
      while (i < lines.length && known.has(lines[i]!.trim())) i++;
      continue;
    }
    if (line.trim() === end) {
      warnings.push(`${file}: found "${end}" without a matching "${start}" line; left it in place.`);
    }
    kept.push(line);
    i++;
  }
  return { kept, hadBlock, dropped, warnings };
}

/**
 * Inserts or replaces the marked block in a gitignore-style file (an empty `lines` array removes
 * it) and reports malformed markers instead of dropping user lines. With `deleteIfEmpty`, a file
 * that held nothing but dfl's block(s) is deleted when the block is removed.
 *
 * A file that is a symbolic link is never written through, replaced or deleted: when the block would
 * change, it is left untouched and a warning says to edit it by hand.
 */
export function updateManagedBlock(
  file: string,
  lines: string[],
  options: ManagedBlockOptions & { deleteIfEmpty?: boolean | undefined } = {},
): ManagedBlockResult {
  const marker = options.marker ?? MANAGED_MARKER;
  const { start, end } = blockBounds(marker);
  const link = isSymlink(file);
  // Through a link the target is only read, to tell whether the block would change.
  const current = link ? (isFile(file) ? readText(file) : undefined) : readTextIfExists(file);
  const text = current ?? '';
  const eol = text.includes('\r\n') ? '\r\n' : '\n';
  const name = options.displayName ?? file;
  const { kept, hadBlock, dropped, warnings } = scan(text, name, marker, [...(options.knownLines ?? []), ...lines]);
  const unique = [...new Set(lines.filter((line) => line.trim() !== ''))];
  // Nothing of dfl's to remove: the file stays byte for byte (no trailing-newline or blank-line cleanup).
  if (unique.length === 0 && !dropped) return { changed: false, warnings, deleted: false };
  while (kept.length > 0 && kept[kept.length - 1] === '') kept.pop();
  const parts: string[] = [...kept];
  if (unique.length > 0) {
    if (parts.length > 0) parts.push('');
    parts.push(start, ...unique, end);
  }
  const next = parts.length > 0 ? parts.join(eol) + eol : '';
  if (current === undefined && next === '') return { changed: false, warnings, deleted: false };
  if (link && next !== text) {
    const what = unique.length > 0 ? `update the "${start}" block in it` : `remove the "${start}" … "${end}" block from it`;
    warnings.push(
      `${name} is a symbolic link, and dfl never writes through or replaces symlinks: ${what} by hand` +
        (unique.length > 0 ? '.' : ' (dfl no longer needs it: every skill dir ignores itself).'),
    );
    return { changed: false, warnings, deleted: false };
  }
  const onlyDfl = hadBlock && warnings.length === 0 && kept.every((line) => line.trim() === '');
  if (next === '' && options.deleteIfEmpty && onlyDfl) {
    removePath(file);
    return { changed: true, warnings, deleted: true };
  }
  if (next === text) return { changed: false, warnings, deleted: false };
  return { changed: writeText(file, next), warnings, deleted: false };
}

/**
 * Inserts or replaces a marked block in a gitignore-style file. An empty `lines` array removes
 * the block. Creates the file when needed. Returns true if changed. Never drops user lines, also
 * when a marker line is missing.
 */
export function upsertManagedBlock(file: string, lines: string[], marker: string = MANAGED_MARKER): boolean {
  return updateManagedBlock(file, lines, { marker }).changed;
}

export function removeManagedBlock(file: string, marker: string = MANAGED_MARKER): boolean {
  if (readTextIfExists(file) === undefined) return false;
  return upsertManagedBlock(file, [], marker);
}

/**
 * Removes the legacy `# >>> dfl (managed) >>>` block from `<root>/.gitignore` (dfl no longer
 * writes it: skill dirs carry their own `.gitignore`). Deletes the file only when it held nothing
 * but that block; a missing end marker never costs user lines (a warning is returned instead).
 * `knownLines` are the lines dfl wrote into the block (the previous manifest's skill dirs + `/`).
 * A symlinked `.gitignore` is left untouched; a warning asks to remove the block by hand.
 */
export function removeLegacyGitignoreBlock(paths: ProjectPaths, knownLines: string[] = []): ManagedBlockResult {
  const file = paths.rootGitignoreFile;
  if (!isSymlink(file) && readTextIfExists(file) === undefined) return { changed: false, warnings: [], deleted: false };
  return updateManagedBlock(file, [], { knownLines, deleteIfEmpty: true, displayName: '.gitignore' });
}
